import json
import zipfile
import xml.etree.ElementTree as ET
import re
import io
import os

# Paths
JSON_PATH = '/root/inventory_data.json'
TEMPLATE_PATH = '/tmp/hwpx_work/template.hwpx'
OUTPUT_PATH = '/root/inventory_report_ready.hwpx'

# XML namespace
NAMESPACES = {
    'hp': 'http://www.hancom.co.kr/hwpml/2010/HWPML'
}

# Register namespaces to preserve them in output
for prefix, uri in NAMESPACES.items():
    ET.register_namespace(prefix, uri)

def load_json_data(path):
    """Load key-value pairs from JSON file."""
    with open(path, 'r', encoding='utf-8') as f:
        return json.load(f)

def get_full_text(element):
    """Get all text content from an element and its children."""
    text_parts = []
    if element.text:
        text_parts.append(element.text)
    for child in element:
        text_parts.extend(get_full_text(child))
        if child.tail:
            text_parts.append(child.tail)
    return ''.join(text_parts)

def find_text_runs(parent, ns):
    """Find all text run elements (<hp:t>) under parent."""
    runs = []
    for elem in parent.iter():
        if elem.tag == f'{{{ns["hp"]}}}t':
            runs.append(elem)
    return runs

def remove_linesegarray(paragraph, ns):
    """Remove layout cache elements from a paragraph."""
    # Find and remove linesegarray elements
    for elem in list(paragraph):
        if elem.tag == f'{{{ns["hp"]}}}linesegarray':
            paragraph.remove(elem)

def merge_and_replace_in_paragraph(paragraph, data, ns):
    """
    Process a paragraph: merge text runs, replace placeholders, remove layout cache if changed.
    Returns True if paragraph was modified.
    """
    # Get all text runs in this paragraph
    runs = find_text_runs(paragraph, ns)

    if not runs:
        return False

    # Concatenate all text content from runs
    full_text = ''.join(run.text or '' for run in runs)

    # Check if any placeholders exist in this paragraph
    placeholder_pattern = r'\{\{[^}]+\}\}'
    placeholders = re.findall(placeholder_pattern, full_text)

    if not placeholders:
        return False

    # Perform replacements
    new_text = full_text
    for key, value in data.items():
        placeholder = f'{{{{{key}}}}}'
        if placeholder in new_text:
            # Convert value to string if needed
            str_value = str(value) if not isinstance(value, str) else value
            new_text = new_text.replace(placeholder, str_value)

    # Clear all but the first run
    first_run = runs[0]
    for run in runs[1:]:
        # Remove the run element from its parent
        parent = find_parent(paragraph, run)
        if parent is not None:
            parent.remove(run)

    # Set the merged and replaced text in the first run
    first_run.text = new_text

    # Remove layout cache elements
    remove_linesegarray(paragraph, ns)

    return True

def find_parent(root, child):
    """Find the parent of a child element."""
    for parent in root.iter():
        for c in parent:
            if c is child:
                return parent
    return None

def process_xml_content(xml_content, data):
    """Process XML content and replace placeholders."""
    # Parse XML
    root = ET.fromstring(xml_content)

    # Find all paragraphs
    ns = NAMESPACES
    paragraphs = []
    for elem in root.iter():
        if elem.tag == f'{{{ns["hp"]}}}p':
            paragraphs.append(elem)

    # Process each paragraph
    modified = False
    for para in paragraphs:
        if merge_and_replace_in_paragraph(para, data, ns):
            modified = True

    # Convert back to string
    return ET.tostring(root, encoding='unicode')

def process_hwpx():
    """Main processing function."""
    # Load data
    data = load_json_data(JSON_PATH)
    print(f"Loaded data with keys: {list(data.keys())}")

    # Process the hwpx file
    with zipfile.ZipFile(TEMPLATE_PATH, 'r') as zin:
        with zipfile.ZipFile(OUTPUT_PATH, 'w', zipfile.ZIP_DEFLATED) as zout:
            for item in zin.infolist():
                content = zin.read(item.filename)

                # Check if this is an XML file that might contain placeholders
                if item.filename.endswith('.xml') or item.filename.endswith('.XML'):
                    try:
                        xml_str = content.decode('utf-8')
                        if '{{' in xml_str:
                            # Process this file
                            print(f"Processing: {item.filename}")
                            processed = process_xml_content(xml_str, data)
                            content = processed.encode('utf-8')
                        else:
                            print(f"Skipping (no placeholders): {item.filename}")
                    except UnicodeDecodeError:
                        print(f"Skipping (not valid UTF-8): {item.filename}")
                else:
                    print(f"Copying (non-XML): {item.filename}")

                zout.writestr(item, content)

    print(f"\nOutput saved to: {OUTPUT_PATH}")

if __name__ == '__main__':
    process_hwpx()

